const rows = $input.all().map(i => i.json);
const today = new Date();
const dayStart = new Date(Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), today.getUTCDate())).getTime();
const MS = 86400000;
function dayDiff(dateStr) {
  if (!dateStr) return null;
  const d = new Date(dateStr + 'T00:00:00Z').getTime();
  return Math.round((d - dayStart) / MS);
}
const out = [];
for (const r of rows) {
  if (String(r.status || '') !== 'confirmed') continue;
  const ci = dayDiff(r.checkin_date);
  const co = dayDiff(r.checkout_date);
  let action = 'none';
  if (ci === 1) action = 'checkin';
  else if (co === 0) action = 'checkout';
  else if (co === -2) action = 'review';
  if (action === 'none') continue;
  out.push({
    booking_id: String(r.booking_id || ''),
    guest_name: String(r.guest_name || ''),
    guest_email: String(r.guest_email || ''),
    property: String(r.property || ''),
    checkin_date: String(r.checkin_date || ''),
    checkout_date: String(r.checkout_date || ''),
    guests: String(r.guests || ''),
    cleaner: String(r.cleaner || ''),
    cleaner_email: String(r.cleaner_email || ''),
    action: action,
    sweep_date: new Date().toISOString().slice(0, 10),
  });
}
return out.map(json => ({ json }));

const agentItem = $input.first().json;
const batch = $('Collect Due Bookings').item.json;
const due = Array.isArray(batch.due) ? batch.due : [];
let parsed = {};
try {
  parsed = JSON.parse(String(agentItem.output || '{}').replace(/```json\n?/g, '').replace(/```/g, ''));
} catch (e) { parsed = {}; }
const msgs = Array.isArray(parsed.messages) ? parsed.messages : [];
const out = msgs.map(m => {
  const bk = due.find(d => String(d.booking_id) === String(m.booking_id)) || {};
  return {
    json: {
      booking_id: bk.booking_id || String(m.booking_id || ''),
      guest_name: bk.guest_name || '',
      guest_email: bk.guest_email || '',
      property: bk.property || '',
      checkin_date: bk.checkin_date || '',
      checkout_date: bk.checkout_date || '',
      guests: bk.guests || '',
      cleaner: bk.cleaner || '',
      cleaner_email: bk.cleaner_email || '',
      action: bk.action || '',
      subject: String(m.subject || ('Message for ' + (bk.property || 'your stay'))),
      message: String(m.message || 'Hello ' + (bk.guest_name || 'there') + ', here is a message about your stay.'),
      sent_at: new Date().toISOString(),
    },
  };
});
if (out.length === 0) {
  const bk = due[0] || {};
  return [{ json: {
    booking_id: bk.booking_id || 'unknown',
    guest_name: bk.guest_name || 'Guest',
    guest_email: bk.guest_email || '',
    property: bk.property || 'the property',
    checkin_date: bk.checkin_date || '',
    checkout_date: bk.checkout_date || '',
    guests: bk.guests || '',
    cleaner: bk.cleaner || '',
    cleaner_email: bk.cleaner_email || '',
    action: bk.action || 'checkin',
    subject: 'Message for ' + (bk.property || 'your stay'),
    message: 'Hello ' + (bk.guest_name || 'there') + ', here is a message about your stay at ' + (bk.property || 'the property') + '.',
    sent_at: new Date().toISOString(),
  } }];
}
return out;

const bookings = $('Read Bookings for Digest').all().map(i => i.json);
const cleaning = $('Read Cleaning Tasks for Digest').all().map(i => i.json);
const today = new Date();
const dayStart = new Date(Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), today.getUTCDate())).getTime();
const MS = 86400000;
function dayDiff(dateStr) {
  if (!dateStr) return null;
  const d = new Date(dateStr + 'T00:00:00Z').getTime();
  return Math.round((d - dayStart) / MS);
}
const upcoming = bookings
  .filter(r => { const d = dayDiff(r.checkin_date); return d !== null && d >= 0 && d <= 7; })
  .sort((a, b) => String(a.checkin_date).localeCompare(String(b.checkin_date)));
const stays = bookings.filter(r => {
  const ci = dayDiff(r.checkin_date); const co = dayDiff(r.checkout_date);
  return ci !== null && co !== null && ci <= 7 && co >= -1;
});
const pending = cleaning.filter(r => String(r.status || '') !== 'done');
const upcomingList = upcoming.slice(0, 5).map(r => r.property + ' ' + r.checkin_date + ' for ' + r.guest_name).join('; ') || 'none';
const pendingList = pending.slice(0, 5).map(r => r.property + ' on ' + r.clean_date + (r.cleaner ? ' (' + r.cleaner + ')' : '')).join('; ') || 'none';
return [{ json: {
  total_bookings: bookings.length,
  upcoming_count: upcoming.length,
  stays_this_week: stays.length,
  pending_cleaning: pending.length,
  upcoming_list: upcomingList,
  pending_list: pendingList,
  digest_date: new Date().toISOString().slice(0, 10),
} }];
